Count only admitted requests within the window (t-5 < s <= t).

```python
def pre(times):
    if len(times) > 7:
        return False
    for x in times:
        if x < 0 or x > 12:
            return False
    for i in range(len(times) - 1):
        if times[i] > times[i + 1]:
            return False
    return True


def post(times, result):
    admitted = []
    count = 0
    for t in times:
        recent = 0
        for s in admitted:
            if t - 5 < s and s <= t:
                recent += 1
        if recent < 3:
            count += 1
            admitted.append(t)
    return result == count
```
